import { toast } from "react-toastify";

export const toastMessageInfo = (message) =>
  toast.info(`${message}`, {
    position: "top-right",
    autoClose: 5000,
    hideProgressBar: false,
    closeOnClick: true,
    pauseOnHover: true,
    draggable: true,
    progress: undefined,
  });

